chapter(14, 'Groups, companies, OTA and website', 'Block six rooms for the Patil wedding, read company accounts and credit limits, handle booking requests from an OTA, and read the direct booking site.',
        'Meera (Manager)', 'manager', menu='Revenue & Sales')
step('Meera is on Modules Home. Group blocks, companies, OTA channels and the booking website are all sales functions of the Revenue & Sales module.', 'Selling rooms in bulk is the manager\'s work.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:manager'], action='read', expect='Modules Home for Meera.', check="ctx.uid==='manager'")
tile('Revenue & Sales', 'Click the Revenue & Sales tile.', 'The sales screens are listed as tiles.', expect='The Revenue & Sales page opens.')
leaf('Revenue & Sales', 'Groups', 'Click the Groups & corporate tile.', 'Blocks, companies, pickup and limit requests are on one page.', expect='The Groups & corporate page opens.', check="ctx.page==='groups'")
read('The figures at the top show the open blocks, the rooms picked up against held, the unpicked rooms and the credit alerts. The tabs are Blocks, Companies, Pickup report, Master folio and Limit requests.', 'A block that is not picked up before its cut-off date should be released to the public.', target='tab:Blocks', expect='The groups page with its tabs.')
click('btn:New group block', 'Click New group block for the Patil wedding.', 'A block holds rooms for a group without naming the guests yet.', expect='The New group block dialog opens.', check="has('Create block')")
step('Type the group name Patil wedding block, arrival 30 Oct, departure 1 Nov and the cut-off 28 Oct.', 'The cut-off is the last day the group may name its guests; after it the unpicked rooms return to sale.', target='field:Group name',
     auto=['type:field:Group name|Patil wedding block', 'type:field:Arrival|2026-10-30', 'type:field:Departure|2026-11-01', 'type:field:Cut-off|2026-10-28'], action='type', expect='The name and the dates are filled.')
step('Hold 2 Classic, 3 Deluxe and 1 Suite, six rooms in all, with the contact Mr. Anil Patil.', 'The rate per type comes from the tariff and can be changed for a group.', target='field:Group contact',
     auto=['click:btn:Increase Classic', 'click:btn:Increase Classic', 'click:btn:Increase Deluxe', 'click:btn:Increase Deluxe', 'click:btn:Increase Deluxe', 'click:btn:Increase Suite', 'type:field:Group contact|Mr. Anil Patil'], action='click', expect='Six rooms are held.')
click('modalbtn:Create block', 'Click Create block.', 'The six rooms are taken out of general sale.', expect='The block GB-1265 is created.', msgText='Group block created')
step('Open the Blocks tab and click the Patil wedding block.', 'The detail shows each room type: held, picked up, released, remaining and free now.', target='btn:Rooming list', auto=['click:tab:Blocks', 'click:btn:Patil wedding block'], action='click', expect='The block detail opens with the Rooming list, Allotment, Release and Cancel block buttons.', check="has('Rooming list')")
click('btn:Rooming list', 'Click Rooming list.', 'The rooming list is where each held room gets a guest name and becomes a booking.', expect='The rooming list opens.')
press('Escape', 'Press Escape. The wedding party will send its names later.', 'Unpicked rooms stay held until the cut-off date.', target='tab:Blocks', expect='The block detail is shown.')
click('tab:Companies', 'Open the Companies tab.', 'Each company account shows its credit limit and its balance.', expect='The company accounts are listed.')
click('btnin:Shree Agro|Credit limit', 'Click Credit limit on Shree Agro Industries.', 'A manager can request a change of limit; the Owner decides.', expect='The credit limit dialog opens.')
press('Escape', 'Press Escape; the limit stays Rs 50,000.', 'Requests appear on the Limit requests tab for the Owner.', target='tab:Limit requests', expect='The Companies tab is shown.')
click('tab:Master folio', 'Open the Master folio tab.', 'A master folio collects the charges of a whole group on one bill.', expect='The master folios are listed.')
click('tab:Pickup report', 'Open the Pickup report tab.', 'The report shows how many held rooms each block has picked up.', expect='The pickup report is listed.')
step('Open OTA channels under Revenue & Sales. OTA means online travel agent, such as TripKart, BookNest and StayHub.', 'Bookings from agents arrive in an inbox and are accepted or rejected here.', target='sel:main h1',
     auto=['key:Escape', 'click:menutop:Revenue & Sales', 'click:menuleaf:OTA channels'], action='click', menu='Revenue & Sales > OTA channels', expect='The OTA channels page opens on the Inbox.', check="ctx.page==='channels'")
read('The Inbox lists new bookings and changes from each channel, with Accept and Reject. Accepting a booking creates a normal reservation with the channel as source and the commission recorded.', 'An unanswered booking may be lost to another hotel, so the inbox is checked often.', target='tab:Inbox', expect='The OTA inbox.')
read('The Pre-check column says whether a booking can be accepted: BookNest BN-88231 for Kiran Joshi, Deluxe, 27 to 29 Oct, shows Can accept, Room 103. Others show Cannot accept, for example when the arrival date is already past or the party is too big for the room.', 'HCC checks the room, the date and the capacity before you accept.', target='row:BN-88231', expect='The pre-check column.')
click('btnin:BN-88231|Accept', 'Click Accept on the BookNest booking BN-88231.', 'The reservation is created and the room is blocked for the guest of the agent.', expect='The booking is accepted and appears in Reservations.')
click('tab:Commission report', 'Open the Commission report tab.', 'The commission the hotel owes each agent is worked out from the accepted bookings.', expect='The commission report opens.')
click('tab:Payouts', 'Open the Payouts tab.', 'Payouts are the payments of the agent to the hotel after the commission; the accountant records them.', expect='The payouts are listed.')
step('Open Direct booking site under Revenue & Sales. Guests who book on the website of the hotel arrive here as web booking requests.', 'Direct bookings carry no commission, so they are the most valuable.', target='sel:main h1',
     auto=['click:menutop:Revenue & Sales', 'click:menuleaf:Direct booking site'], action='click', menu='Revenue & Sales > Direct booking site', expect='The Direct booking site page opens on Bookings.', check="ctx.page==='booking-site'")
click('tab:Preview', 'Open the Preview tab.', 'The preview shows the page guests see on the website, including the QR code that opens the feedback form.', expect='The preview of the booking page opens.')
